update_rule.pseudocode:
if t == 0:
  if network_type == 'small_world':
    G = watts_strogatz_graph(population_size, k=avg_degree, beta=network_rewire_prob)
  elif network_type == 'erdos_renyi':
    p = avg_degree/(population_size-1)
    G = erdos_renyi_graph(population_size, p)
  adjacency_list = G.neighbors()

if t == 0:
  counts = multinomial(location_count_total, [mix_workplaces, mix_schools, mix_retail, mix_transit])
  create that many locations per type with capacities, hours_open, enforcement_level = base_enforcement_multiplier_type
  store visit_rates.by_type = {workplaces: visit_rate_workplaces, ...}

if t == 0:
  create retailer_count retailers with inventory_level = round(mask_availability * retailer_inventory_per_capita * population_size / retailer_count)
  set mask_price and restock_rate
  set accessibility ~ Uniform(0.5,1.0)
else:
  for r in retailers:
    added = Binomial(n=max(0, round(restock_rate * population_size / retailer_count)), p=0.5)
    r.inventory_level += added
    r.stockout_flag = (r.inventory_level == 0)

if t == 0:
  instantiate media_channels_count channels with reach, credibility, message_valence
for each person:
  delta_risk = 0; delta_trust = 0
  for each channel:
    if person targeted by channel with prob channel.reach * (1 + 0.2*(person.group_identity==targeted_group)-0.1):
      signal = channel.message_valence + authority.campaign_signal
      misinformation_factor = (1 - misinformation_level) if signal>0 else (1 + misinformation_level)
      eff_signal = signal * channel.credibility * misinformation_factor
      delta_risk += media_effect_weight * eff_signal
      delta_trust += trust_update_rate * channel.credibility * sign(eff_signal)
  media.delta_risk_perception[person] = clip(delta_risk, -0.5, 0.5)
  media.delta_trust[person] = clip(delta_trust, -0.1, 0.1)

if t < policy_start_day:
  mandate_status = false
else:
  if metrics.adoption_rate_latest < 0.6:
    mandate_status = true
  else if metrics.adoption_rate_latest > 0.85:
    mandate_status = false
  enforcement_strength = clip(enforcement_strength + 0.05*(0.7 - metrics.adoption_rate_latest), 0, 1)
  campaign_signal = campaign_intensity * authority_message_valence
policy_state = {status: mandate_status, scope: mandate_scope, enforcement_strength: enforcement_strength, fine_amount: fine_amount}

visits = []
for person in persons:
  for loc_type in ['workplaces','schools','retail','transit']:
    if Bernoulli(visit_rates.by_type[loc_type]):
      loc = random_location_of_type(loc_type)
      visits.append((person.id, loc.id, loc_type))
      person.last_location_type = loc_type
# Update norms from previous day's observed wearing at each location type
for loc_type in ['workplaces','schools','retail','transit']:
  wearing = [persons[p].wears_mask for (p,l,t) in visits if t==loc_type]
  rate = mean(wearing) if len(wearing)>0 else 0
  locations.norm_signal[loc_type] = (1 - normative_signal_weight) * locations.norm_signal.get(loc_type, 0.0) + normative_signal_weight * rate
